package com.hrm.gui;

import com.hrm.config.DBConnection;
import com.hrm.util.CsvExporter;
import javax.swing.*;
import java.awt.*;
import java.math.BigDecimal;
import java.sql.*;
import java.time.LocalDate;

/** Quản lý hợp đồng lao động, dùng bảng employee_contracts có sẵn trong schema. */
public class ContractsPanel extends JPanel {
    private final JTable table=Ui.table(new String[]{"Mã HĐ","Mã NV","Họ tên","Số hợp đồng","Loại hợp đồng","Ngày bắt đầu","Ngày kết thúc","Lương hợp đồng","Trạng thái"});
    public ContractsPanel(){Ui.init();setLayout(new BorderLayout(0,10));setBackground(Ui.BG);
        JPanel actions=new JPanel(new FlowLayout(FlowLayout.LEFT,8,8));actions.setBackground(Ui.BG);JButton add=Ui.primaryBtn("+ Tạo hợp đồng"),terminate=Ui.dangerBtn("Chấm dứt hợp đồng"),refresh=Ui.btn("Làm mới"),export=Ui.btn("Xuất Excel/CSV");actions.add(add);actions.add(terminate);actions.add(refresh);actions.add(export);
        JPanel north=new JPanel(new BorderLayout());north.setBackground(Ui.BG);north.add(Ui.top("Hợp đồng lao động","Tạo, tra cứu và theo dõi hiệu lực hợp đồng nhân viên"),BorderLayout.NORTH);north.add(actions,BorderLayout.SOUTH);add(north,BorderLayout.NORTH);add(Ui.scroll(table),BorderLayout.CENTER);
        add.addActionListener(e->create());terminate.addActionListener(e->terminate());refresh.addActionListener(e->load());export.addActionListener(e->CsvExporter.export(this,table,"bao_cao_hop_dong.csv"));load();}
    private void load(){try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("UPDATE employee_contracts SET status='EXPIRED' WHERE status='ACTIVE' AND end_date IS NOT NULL AND end_date<CURRENT_DATE")){p.executeUpdate();}catch(Exception ignored){} String sql="SELECT c.contract_id,c.employee_id,e.full_name,c.contract_no,c.contract_type,c.start_date,c.end_date,c.salary,c.status FROM employee_contracts c JOIN employees e ON e.employee_id=c.employee_id ORDER BY c.contract_id DESC";
        try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(sql);ResultSet r=p.executeQuery()){var m=(javax.swing.table.DefaultTableModel)table.getModel();m.setRowCount(0);while(r.next())m.addRow(new Object[]{r.getLong(1),String.format("NV%04d",r.getInt(2)),r.getString(3),r.getString(4),r.getString(5),r.getDate(6),r.getDate(7),r.getBigDecimal(8),r.getString(9)});}catch(Exception e){Ui.error(this,e);}}
    private void create(){JTextField emp=new JTextField(),no=new JTextField(),type=new JTextField("Xác định thời hạn"),start=new JTextField(LocalDate.now().toString()),end=new JTextField(),salary=new JTextField();JPanel f=new JPanel(new GridLayout(0,2,8,8));f.add(new JLabel("Mã nhân viên (số)"));f.add(emp);f.add(new JLabel("Số hợp đồng"));f.add(no);f.add(new JLabel("Loại hợp đồng"));f.add(type);f.add(new JLabel("Ngày bắt đầu YYYY-MM-DD"));f.add(start);f.add(new JLabel("Ngày kết thúc (để trống nếu không thời hạn)"));f.add(end);f.add(new JLabel("Lương hợp đồng"));f.add(salary);
        if(JOptionPane.showConfirmDialog(this,f,"Tạo hợp đồng lao động",JOptionPane.OK_CANCEL_OPTION,JOptionPane.PLAIN_MESSAGE)!=JOptionPane.OK_OPTION)return;
        try{int employeeId=Integer.parseInt(emp.getText().trim());String contractNo=no.getText().trim();String contractType=type.getText().trim();LocalDate s=LocalDate.parse(start.getText().trim());LocalDate en=end.getText().trim().isEmpty()?null:LocalDate.parse(end.getText().trim());BigDecimal pay=new BigDecimal(salary.getText().trim());if(contractNo.isBlank()||contractType.isBlank()||pay.signum()<0||(en!=null&&en.isBefore(s)))throw new IllegalArgumentException("Vui lòng kiểm tra số hợp đồng, loại hợp đồng, ngày và lương.");
            try(Connection c=DBConnection.getConnection()){try(PreparedStatement check=c.prepareStatement("SELECT status FROM employees WHERE employee_id=?")){check.setInt(1,employeeId);try(ResultSet r=check.executeQuery()){if(!r.next())throw new IllegalArgumentException("Không tìm thấy nhân viên.");if(!"ACTIVE".equals(r.getString(1)))throw new IllegalArgumentException("Không thể tạo hợp đồng cho nhân viên đã nghỉ việc.");}} try(PreparedStatement p=c.prepareStatement("INSERT INTO employee_contracts(employee_id,contract_no,contract_type,start_date,end_date,salary,status) VALUES(?,?,?,?,?,?,?)")){p.setInt(1,employeeId);p.setString(2,contractNo);p.setString(3,contractType);p.setDate(4,Date.valueOf(s));if(en==null)p.setNull(5,Types.DATE);else p.setDate(5,Date.valueOf(en));p.setBigDecimal(6,pay);p.setString(7,"ACTIVE");p.executeUpdate();}}load();JOptionPane.showMessageDialog(this,"Đã tạo hợp đồng.");
        }catch(Exception e){JOptionPane.showMessageDialog(this,"Không thể tạo hợp đồng: "+e.getMessage(),"Lỗi",JOptionPane.ERROR_MESSAGE);}}
    private void terminate(){int row=table.getSelectedRow();if(row<0){JOptionPane.showMessageDialog(this,"Hãy chọn hợp đồng.");return;}if(!"ACTIVE".equals(table.getValueAt(row,8).toString())){JOptionPane.showMessageDialog(this,"Chỉ có thể chấm dứt hợp đồng đang ACTIVE.");return;}if(JOptionPane.showConfirmDialog(this,"Chấm dứt hợp đồng đã chọn?","Xác nhận",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("UPDATE employee_contracts SET status='TERMINATED' WHERE contract_id=? AND status='ACTIVE'")){p.setLong(1,Long.parseLong(table.getValueAt(row,0).toString()));p.executeUpdate();load();}catch(Exception e){Ui.error(this,e);}}
}
